('NHIS_DECREE','{"instrument":"국민건강보험법 시행령","article":"제9조제1호","promulgation":"대통령령 제34497호","enforced_on":"2024-05-20","source_url":"https://www.law.go.kr/LSW/lsInfoR.do?lsiSeq=262519&efYd=20240520&chrClsCd=010202"}'::jsonb)
), assigned AS (
 SELECT s.code,s.effective_from,jsonb_agg(r.citation ORDER BY r.key) AS citations FROM statutory_rules s
 CROSS JOIN LATERAL (SELECT DISTINCT ON (key) key,citation FROM refs
 WHERE key=ANY(CASE s.filing_rule->>'insurer'
 WHEN 'NPS' THEN ARRAY['NPS_ACT','NPS_DECREE'] WHEN 'NHIS' THEN ARRAY['NHIS_ACT','NHIS_DECREE']
 WHEN 'EI' THEN ARRAY['EI_ACT','EI_DECREE'] ELSE ARRAY['IACI_ACT','IACI_DECREE','EI_DECREE'] END)
 AND (citation->>'enforced_on')::date<=s.effective_from ORDER BY key,citation->>'enforced_on' DESC) r
 WHERE s.filing_rule IS NOT NULL AND s.effective_from>=DATE '2024-01-01' GROUP BY s.code,s.effective_from)
UPDATE statutory_rules s SET filing_rule=s.filing_rule || jsonb_build_object('applicability_citations',a.citations) FROM assigned a WHERE s.code=a.code AND s.effective_from=a.effective_from;
-- From 2024 the verified exclusion clauses match these earlier primary versions.
WITH policy AS (SELECT DISTINCT ON(code) code,filing_rule FROM statutory_rules WHERE filing_rule IS NOT NULL
 AND COALESCE((filing_rule->>'applicability_unverified')::boolean,false)=false ORDER BY code,effective_from)
UPDATE statutory_rules s SET filing_rule=s.filing_rule || jsonb_build_object('applicability_unverified',false,'exclusions',p.filing_rule->'exclusions')
FROM policy p WHERE s.code=p.code AND s.effective_from>=DATE '2024-01-01' AND s.filing_rule->>'applicability_unverified'='true';
